function createEmitter() {
  const listeners = [];
  return {
    on(fn) {
      listeners.push(fn);
      return () => {
        const i = listeners.indexOf(fn);
        if (i !== -1) listeners.splice(i, 1);
      };
    },
    emit(data) {
      listeners.forEach((fn) => fn(data));
    }
  };
}

