const assert = require('node:assert');

function createSpy() {
  const spy = (...args) => spy.calls.push(args);
  spy.calls = [];
  return spy;
}

function calledWith(spy, ...expectedArgs) {
  return spy.calls.some((callArgs) => {
    try {
      assert.deepStrictEqual(callArgs, expectedArgs);
      return true;
    } catch {
      return false;
    }
  });
}

const notify = createSpy();
notify('order-1', { status: 'shipped' });
notify('order-2', { status: 'pending' });

console.log(calledWith(notify, 'order-1', { status: 'shipped' }));
console.log(calledWith(notify, 'order-1', { status: 'cancelled' }));

