function* naturals() {
  let n = 1;
  while (true) {
    console.log('generating', n);
    yield n++;
  }
}
function take(iterable, n) {
  const result = [];
  const it = iterable[Symbol.iterator]();
  for (let i = 0; i < n; i++) {
    const { value, done } = it.next();
    if (done) break;
    result.push(value);
  }
  return result;
}
console.log(take(naturals(), 3));

